INSERT INTO `courses` (`id`, `user_id`, `category_id`, `title`, `slug`, `description`, `thumbnail`, `is_public`, `created_at`, `updated_at`) VALUES
	(1, 20, 1, 'Figma cơ bản cho người mới', 'ut-adipisci-nemo-rllTu', 'Harum iure doloremque sed autem. Sint molestias qui iusto ut voluptate sapiente amet id. Eum eos sint laborum et. Recusandae quia aut eos laboriosam blanditiis vel. Cumque eveniet accusantium sit commodi nulla dolores.', '/storage/thumbnails/CgtrfVyW8QKZgqrmEuRy2tx95Qqzw2JwfsLRBiZj.jpg', 1, '2025-11-09 21:08:24', '2025-11-24 23:26:13'),
	(2, 10, 1, 'Python cơ bản đến nâng cao', 'aliquam-non-deserunt-pariatur-dolores-xk2Ig', 'Vitae unde enim amet reprehenderit est dolore. Quia pariatur voluptatibus at esse molestiae alias. Quae sunt voluptatem praesentium alias magni.', '/storage/thumbnails/t0aAUU8pyk67Z4iAJz3mTiDBAV0TK2LMk5RheBLO.jpg', 1, '2025-11-09 21:08:24', '2025-11-24 23:26:34'),
	(59, 1, 1, 'JavaScript Cơ bản', 'newver-TKXCz', 'Javascript có thể làm được gì? Giới thiệu về trang F8 | Học lập trình Javascript cơ bản', '/storage/thumbnails/U11szHeMihdILZdT08TIqpdu3NtPNunaXmvV8ZQC.png', 1, '2025-11-22 07:43:58', '2025-11-24 23:17:45'),
	(60, 1, 1, 'Khóa Học HTML CSS cơ bản', 'khoa-hoc-html-css-co-ban-P8IpC', 'Tham gia các khóa học MIỄN PHÍ của chúng tôi (đã quyết định theo thì hãy cố gắng đến cùng)', '/storage/thumbnails/6zVGMfnlrIXUj9x3XKmwBzzrTmG4rL8zMpvplKZd.png', 1, '2026-01-09 07:38:09', '2026-01-09 07:38:09'),
	(61, 1, 1, 'Python cho người mới bắt đầu', 'python-cho-nguoi-moi-bat-dau-xNGG3', 'Khóa học Lập trình Python: bao gồm tất cả nội dung kiến thức cơ bản về Python, Các thuật toán, Lập trình hướng đối tượng Python, Cấu trúc dữ liệu, Xử lý tập tin trong, Lập trình giao diện.\r\nKhóa học này cung cấp phần lớn kiến thức và kỹ năng về ngôn ngữ lập trình Python và là bước đệm cho các lập trình viên muốn tìm hiểu sâu về Python.\r\nKhóa học này phù hợp cho các bạn mới bắt đầu học Lập trình Python, hoặc các bạn muốn ôn tập lại kiến thức một cách hệ thống và mạch lạc để chuẩn bị đi làm.', '/storage/thumbnails/LuEHA72rOsuZo3h0OHY6LIYxojZCSzhD9OPwf0iK.jpg', 1, '2026-01-09 19:07:25', '2026-01-09 19:07:25'),
	(62, 1, 1, 'PHP cơ bản cho người mới', 'php-co-ban-cho-nguoi-moi-zM3uf', 'Mình sẽ cố gắng hết sức để tốt cho việc học của các bạn\r\nNếu các bạn cần hổ trợ hoặc hỏi đáp thì các bạn có thể liên hệ với  tôi qua trang Fanpage của Facebook', '/storage/thumbnails/9r0z1IT22mcxAU5wkF1kl58PoZ18mpGckk36BqnS.jpg', 1, '2026-01-09 19:10:10', '2026-01-09 19:10:10');
