INSERT INTO `course_lessons` (`id`, `chapter_id`, `title`, `content`, `type`, `video_url`, `duration_seconds`, `is_free_preview`, `order`, `created_at`, `updated_at`) VALUES
	(1, 1, 'Figma cơ bản', 'Figma cơ bản - Bài 1: Làm quen với Figma | kaorumap', 'video', 'https://www.youtube.com/watch?v=f1VYYjEhX2Q&list=PLZ52njWO5oxKNf7ZxH1YjH4lU80QefcZH', 0, 1, 1, '2025-11-21 20:35:29', '2025-12-04 03:43:45'),
	(2, 1, 'Tập sử dụng Figma', 'Figma cơ bản - Bài 2 cho người mới bắt đầu\nThực hành sử dụng Figma\nDùng Figma thực hành vẽ lại 1 thiết kế có sẵn', 'video', 'https://www.youtube.com/watch?v=aOptfPIWAVU&list=PLZ52njWO5oxKNf7ZxH1YjH4lU80QefcZH&index=2', 0, 1, 2, '2025-11-21 20:37:39', '2025-12-04 03:44:45'),
	(3, 2, 'Component - Instance - Variants', 'Figma cơ bản - Bài 3 cho người mới bắt đầu:\nTạo và sử dụng Component, Instances, Variants trong Figma\nFigma for beginners: create and use Component, Instance, and Variants in Figma', 'video', 'https://www.youtube.com/watch?v=rzBg1X_yx90&list=PLZ52njWO5oxKNf7ZxH1YjH4lU80QefcZH&index=3', 0, 1, 1, '2025-11-21 20:39:03', '2025-12-04 03:45:43'),
	(4, 53, 'Javascript có thể làm được gì?', 'Xin chào các bạn, trong video đầu tiên của khóa học JavaScript cơ bản này mình sẽ chia sẻ với các bạn Javascript có thể làm được gì? Giới thiệu về trang F8 | Học lập trình Javascript cơ bản.\n#hoclaptrinh  #hoclaptrinhmienphi  #javascript  #frontend  #backend  #devops  #f8', 'video', 'https://www.youtube.com/watch?v=0SJE9dYdpps&list=PL_-VfJajZj0VgpFpEVFzS5Z-lkXtBe-x5', 0, 0, 1, '2025-11-24 23:21:45', '2025-11-24 23:21:45'),
	(5, 53, 'Lời khuyên trước khóa học', 'Chào các bạn, video thứ 2 này là chia sẻ của mình tới các bạn về những lưu ý và lời khuyên trước khóa học | Lộ trình khóa học JavaScript cơ bản tại F8\n#hoclaptrinh  #hoclaptrinhmienphi  #javascript  #frontend  #backend  #devops  #f8', 'video', 'https://www.youtube.com/watch?v=-jV06pqjUUc&list=PL_-VfJajZj0VgpFpEVFzS5Z-lkXtBe-x5&index=2', 0, 0, 2, '2025-11-24 23:23:39', '2025-11-24 23:23:39'),
	(6, 53, 'Cài đặt môi trường', 'Video này mình sẽ hướng dẫn các bạn cài đặt môi trường, công cụ phù hợp để học JavaScript\n#hoclaptrinh  #hoclaptrinhmienphi  #javascript  #frontend  #backend  #devops  #f8', 'video', 'https://www.youtube.com/watch?v=efI98nT8Ffo&list=PL_-VfJajZj0VgpFpEVFzS5Z-lkXtBe-x5&index=3', 0, 0, 3, '2025-11-24 23:24:29', '2025-11-24 23:24:29'),
	(7, 2, 'Constraints & Auto Layout', 'Figma cơ bản - Bài 4 cho người mới bắt đầu\nTìm hiểu và sử dụng Constraints & Auto Layout trong Figma để tạo ra những thiết kế có thể linh hoạt thay đổi kích thước\nUsing Constraints & Auto Layout in Figma', 'video', 'https://www.youtube.com/watch?v=7xP8kP4EHHo&list=PLZ52njWO5oxKNf7ZxH1YjH4lU80QefcZH&index=4', 0, 1, 2, '2025-11-27 03:09:38', '2025-12-04 03:46:47'),
	(8, 2, 'Prototypes', 'Figma cơ bản - Bài 5 cho người mới bắt đầu:\nHướng dẫn tạo Prototype trong Figma', 'video', 'https://www.youtube.com/watch?v=hhIOgo0W_t8&list=PLZ52njWO5oxKNf7ZxH1YjH4lU80QefcZH&index=5', 0, 1, 3, '2025-11-27 03:10:57', '2025-12-04 03:47:24'),
	(12, 3, 'Interactive Components with Variants', 'Figma - Bài 6 cho người mới bắt đầu:\nĐăng và sử dụng Interactive Components with Variants với Figma beta', 'video', 'https://www.youtube.com/watch?v=6cnKCE8bbjE&list=PLZ52njWO5oxKNf7ZxH1YjH4lU80QefcZH&index=6', 0, 1, 1, '2025-12-04 03:48:15', '2025-12-04 03:48:15'),
	(13, 55, 'Cấu trúc file HTML | Khởi tạo folder dự án trong HTML', 'Video này giới thiệu đến các bạn những cấu chúc đơn giản của một file HTML, hướng dẫn khởi tạo folder dự án và giới thiệu một số thẻ cơ bản.', 'video', 'https://www.youtube.com/watch?v=LYnrFSGLCl8&list=PL_-VfJajZj0U9nEXa4qyfB4U5ZIYCMPlz&index=5', 0, 1, 1, '2026-01-09 07:44:08', '2026-01-09 07:44:08'),
	(14, 55, 'Comments trong HTML | Cú pháp mở và đóng Comments', 'Video này giới thiệu tới các bạn về Comments trong HTML, mục đích sử dụng cũng như cú pháp mở và đóng Comments.', 'video', 'https://www.youtube.com/watch?v=JG0pdfdKjgQ&list=PL_-VfJajZj0U9nEXa4qyfB4U5ZIYCMPlz&index=6', 0, 1, 2, '2026-01-09 07:44:50', '2026-01-09 07:44:50'),
	(15, 55, 'Những thẻ HTML thông dụng', 'Bài học này giới thiệu tới các bạn những thẻ HTML thường được sử dụng trong  quá trình xây dựng một website. Bao gồm tên thẻ, ý nghĩa, cách sử dụng và trường hợp sử dụng thẻ.', 'video', 'https://www.youtube.com/watch?v=AzmdwZ6e_aM&list=PL_-VfJajZj0U9nEXa4qyfB4U5ZIYCMPlz&index=7', 0, 1, 3, '2026-01-09 07:45:34', '2026-01-09 07:45:34'),
	(16, 55, 'Attributes trong HTML | Thêm thuộc tính (Attributes) vào thẻ', 'Ở video này chúng ta cùng tìm hiểu về khái niệm Attributes và cách thêm thuộc tính (Attributes) vào một thẻ trong HTML.', 'video', 'https://www.youtube.com/watch?v=UYpIh5pIkSA&list=PL_-VfJajZj0U9nEXa4qyfB4U5ZIYCMPlz&index=8', 0, 1, 4, '2026-01-09 07:46:21', '2026-01-09 07:46:21'),
	(17, 56, 'Cách sử dụng CSS trong HTML | Hướng dẫn chi tiết của từng cách', 'Video này chúng ta cùng tìm hiểu về các cách sử dụng CSS trong file HTML và chi tiết cụ thể của từng cách.', 'video', 'https://www.youtube.com/watch?v=NsSsJTg29oE&list=PL_-VfJajZj0U9nEXa4qyfB4U5ZIYCMPlz&index=9', 0, 1, 1, '2026-01-09 07:47:08', '2026-01-09 07:47:08'),
	(18, 56, 'ID và Class trong CSS selectors', 'Trong bài này chúng ta cùng tìm hiểu về khái niệm ID và Class trong CSS selectors. Cách sử dụng ID & Class.', 'video', 'https://www.youtube.com/watch?v=4J6d8cr0X48&list=PL_-VfJajZj0U9nEXa4qyfB4U5ZIYCMPlz&index=10', 0, 1, 2, '2026-01-09 07:47:54', '2026-01-09 07:47:54'),
	(19, 56, 'Mức độ ưu tiên trong CSS', 'Video này chúng ta cùng tìm hiểu về các mức độ ưu tiên khi sử dụng CSS, ví dụ về các trường hợp ưu tiên trong CSS.', 'video', 'https://www.youtube.com/watch?v=AgZ0PX28bnA&list=PL_-VfJajZj0U9nEXa4qyfB4U5ZIYCMPlz&index=11', 0, 1, 3, '2026-01-09 07:48:42', '2026-01-09 07:48:42'),
	(20, 57, 'Thuộc tính Padding trong CSS | CSS Padding', '☻ Phần mềm sử dụng trong video:\nCông cụ dịch Tiếng Anh: http://bit.ly/2Wsuhet\nCông cụ đo đạc giao diện web: http://bit.ly/3muevdD\nCông cụ viết CV xin việc chuyên nghiệp: https://mycv.vn', 'video', 'https://www.youtube.com/watch?v=aj-lD4XXr8A&list=PL_-VfJajZj0U9nEXa4qyfB4U5ZIYCMPlz&index=14', 0, 1, 1, '2026-01-09 07:49:44', '2026-01-09 07:49:44');
