	(231, 1, 'Đơn tuyển dụng - Java', 'Mẫu CV giới thiệu - Java, tài liệu mới danh cho sinh viên hỗ trợ viết CV', 'http://localhost:8000/storage/media/18/[TPS]_-Fresher-Java-Engineer.pdf', 'application/pdf', 127438, 'http://localhost:8000/storage/media/19/meme-cho.png', 0, 'published', '2025-11-15 06:50:31', '2026-01-09 18:19:40', 1),
	(234, 1, 'Đề thi web Hackathon 2025', 'Đề thi web Hackathon 2025 dành cho mọi người yêu thích lập trình web', 'http://localhost:8000/storage/media/22/De-thi-Hackathon-2025_unlocked.pdf', 'application/pdf', 218842, 'http://localhost:8000/storage/media/23/z6184844873207_54d93bc234a75edd1862e5f6363dd780.jpg', 1, 'published', '2025-11-22 03:56:12', '2025-12-04 04:37:26', 1),
	(235, 1, 'Đề cương ôn tập', 'Đề cương ôn tập phiên bản mới, tổng hợp kiến thức các môn học', 'http://localhost:8000/storage/media/24/decuong01.pdf', 'application/pdf', 682744, 'http://localhost:8000/storage/media/25/z6184844873207_54d93bc234a75edd1862e5f6363dd780.jpg', 0, 'published', '2025-11-22 04:05:39', '2026-01-09 18:22:24', 3),
	(236, 1, 'Lập trình Servlet với Java', 'Lập trình Servlet với Java kkkkkkkkkkkkkk', 'http://localhost:8000/storage/media/33/Bài-thực-hành-tuần-5.pdf', 'application/pdf', 711640, NULL, 0, 'published', '2025-12-04 04:43:45', '2025-12-04 04:43:45', 1),
	(237, 1, 'Bài tập Lập trình Java', 'Lập trình java cơ bản dành cho người mới bắt đầu, bài thực hành', 'http://localhost:8000/storage/media/35/Bai-thuc-hanh-buoi-2.pdf', 'application/pdf', 300271, NULL, 0, 'published', '2026-01-09 18:23:46', '2026-01-09 18:23:46', 1);
INSERT INTO `exams` (`id`, `title`, `description`, `category_id`, `difficulty`, `duration`, `color`, `passing_score`, `max_attempts`, `learning_objectives`, `prerequisites`, `tags`, `status`, `is_ai_generated`, `created_at`, `updated_at`) VALUES
	(202, 'Máy Tính Cơ Bản (Mức Độ Dễ)', 'Bài kiểm tra này giúp đánh giá kiến thức nền tảng và cơ bản nhất của người học về cấu tạo và chức năng của máy tính, bao gồm phần cứng và phần mềm.', 3, 'Beginner', 10, '#004488', 70, 5, '["Et et quia omnis non odio.", "Cum eos et quis.", "Occaecati nobis minima rem soluta ex eum expedita eligendi.", "Repellat et unde id corrupti laborum quia deleniti."]', '["numquam", "sequi", "perferendis"]', '["ullam", "vitae", "commodi"]', 'published', b'0', '2025-09-04 18:41:51', '2025-12-04 06:01:03'),
	(203, 'Toán học lượng tử', 'Khái niệm cơ bản về Toán học lượng tử và những định luật mới', 4, 'Advanced', 20, '#00cc66', 70, 5, '["Qui accusamus cumque porro placeat veniam.", "Nisi fugiat amet fugit nobis est est aut.", "Nihil eum quod quisquam vel consequatur.", "Cupiditate non iure iure sequi."]', '["quis", "sunt", "voluptates"]', '["et", "nesciunt", "asperiores"]', 'published', b'0', '2025-09-04 18:41:51', '2025-12-16 19:38:12'),
	(204, 'Khoa học dữ liệu tiên tiến', 'Khám phá về Big data và Cloud, AWS,... Những kiến thức mới về không gian mạng', 3, 'Intermediate', 15, '#0000ff', 70, 3, '["Culpa vel quaerat autem consequatur et repellat.", "Sed est corporis rerum sequi voluptatum.", "Pariatur quis similique quasi est.", "Praesentium occaecati et ad."]', '["recusandae", "aspernatur", "ipsum"]', '["ea", "fugit", "natus"]', 'published', b'0', '2025-09-04 18:41:51', '2025-12-16 19:40:36'),
	(306, 'Test nhanh An toàn thông tin', 'Kiểm tra kiến thức cơ bản về an toàn thông tin', 3, 'Beginner', 15, '#4d09ec', 70, 5, '["Hiểu được tầm quan trọng của an toàn thông tin trong kỷ nguyên số.", "Nhận biết các nguy cơ mất an toàn thông tin và các loại hình tấn công.", "Nắm bắt các xu hướng phát triển của công nghệ thông tin và truyền thông liên quan đến an toàn thông tin."]', '["Kiến thức cơ bản về công nghệ thông tin và truyền thông (CNTT&TT).", "Hiểu biết về mạng máy tính và Internet."]', '["an toàn thông tin", "CNTT&TT", "nguy cơ", "bảo mật", "không gian mạng"]', 'draft', b'1', '2026-01-09 09:43:47', '2026-01-09 09:43:47'),
	(307, 'Machine Learning nang cao', 'Học máy nang cao, dành cho người co ky nang, mức độ kho, lý thuyết', 3, 'Intermediate', 15, '#3B82F6', 68, 5, '["Hiểu các khái niệm cơ bản về Machine Learning.", "Phân biệt được các loại thuật toán Machine Learning phổ biến.", "Nắm được quy trình xây dựng một mô hình Machine Learning đơn giản.", "Nhận biết được các ứng dụng của Machine Learning trong thực tế."]', '["Kiến thức cơ bản về toán học (đại số tuyến tính, xác suất thống kê).", "Hiểu biết về lập trình (Python là lợi thế)."]', '["Machine Learning", "Học máy", "AI", "Thuật toán", "Python"]', 'draft', b'1', '2026-01-09 10:54:39', '2026-01-09 10:54:39'),
	(308, 'Machine Learning cơ bản', 'Học máy cơ bản, dành cho người mới bắt đầu, mức độ dễ, lý thuyết', 3, 'Intermediate', 15, '#3B82F6', 68, 5, '["Hiểu các khái niệm cơ bản của Machine Learning.", "Phân biệt được các loại Machine Learning chính (Supervised, Unsupervised, Reinforcement).", "Nắm bắt được quy trình xây dựng một mô hình Machine Learning đơn giản.", "Nhận biết được một số thuật toán Machine Learning phổ biến."]', '["Kiến thức cơ bản về toán học (đại số tuyến tính, xác suất thống kê).", "Hiểu biết về lập trình (Python là lợi thế)."]', '["machine learning", "học máy", "supervised learning", "unsupervised learning", "classification", "regression"]', 'draft', b'1', '2026-01-09 10:55:01', '2026-01-09 10:55:01'),
	(309, 'Phân vùng ảnh TGMT', 'Thị giác máy tính phần Phân vùng ảnh, kiến thức cơ bản của python và openCV', 1, 'Beginner', 20, '#1116b6', 70, 5, '["Understand the concept of image segmentation and its purpose.", "Identify and apply different thresholding techniques for image segmentation.", "Describe the principles behind region-based and edge-based segmentation methods.", "Explain the basic morphological operations used in image processing.", "Understand the concept of contours and how to find them in images."]', '["Basic knowledge of image processing concepts", "Familiarity with image representation (pixels, grayscale values)", "Understanding of basic programming concepts"]', '["image segmentation", "thresholding", "computer vision", "image processing", "contours"]', 'draft', b'1', '2026-01-09 11:08:09', '2026-01-09 11:08:09'),
	(310, 'Deep learning cho người mới bắt đầu', 'Kiến thức Deep learning cho người mới bắt đầu, áp dụng các thuật toán khác nhau', 3, 'Intermediate', 25, '#172ede', 70, 5, '["Hiểu được khái niệm mạng nơ-ron nhân tạo (Artificial Neural Network - ANN).", "Phân biệt được các loại lớp (layer) phổ biến trong Deep Learning.", "Nắm vững khái niệm hàm kích hoạt (activation function) và vai trò của nó.", "Hiểu được quá trình huấn luyện mạng nơ-ron (training) và các thuật toán tối ưu hóa cơ bản."]', '["Kiến thức cơ bản về đại số tuyến tính.", "Hiểu biết về giải tích.", "Khái niệm cơ bản về Machine Learning."]', '["Deep Learning", "Mạng nơ-ron", "Machine Learning", "AI", "Học sâu"]', 'draft', b'1', '2026-01-09 11:12:09', '2026-01-09 11:12:09'),
	(311, 'Tìm hiểu về ngành IT', 'Công nghệ thông tin là gì, tìm hiểu về ngành Công nghệ thông tin và ứng dụng', 3, 'Intermediate', 20, '#3077e8', 70, 5, '["Hiểu rõ khái niệm và vai trò của Công nghệ Thông tin trong xã hội hiện đại.", "Nhận biết các lĩnh vực ứng dụng phổ biến của Công nghệ Thông tin.", "Nắm bắt các xu hướng phát triển mới nhất trong ngành Công nghệ Thông tin.", "Phân biệt được các chuyên ngành chính trong Công nghệ Thông tin."]', '["Kiến thức cơ bản về máy tính và internet.", "Sự quan tâm đến công nghệ và ứng dụng của nó."]', '["Công nghệ thông tin", "Ứng dụng CNTT", "Lập trình", "Mạng máy tính", "Phát triển phần mềm"]', 'draft', b'1', '2026-01-09 11:17:34', '2026-01-09 11:17:34'),
	(312, 'Câu hỏi về AI', 'Tổng hợp các kiến thức về AI, ứng dụng của nó trong đời sống hiện nay?', 3, 'Beginner', 25, '#79b003', 70, 3, '["Hiểu các khái niệm cơ bản về Trí tuệ Nhân tạo (AI).", "Nhận biết các loại AI khác nhau (ví dụ: AI hẹp, AI tổng quát, AI siêu việt).", "Nắm bắt các ứng dụng phổ biến của AI trong các lĩnh vực khác nhau.", "Đánh giá tác động của AI đối với xã hội và tương lai."]', '["Kiến thức cơ bản về khoa học máy tính.", "Hiểu biết về thuật toán và lập trình (không bắt buộc nhưng hữu ích)."]', '["AI", "Trí tuệ nhân tạo", "Machine Learning", "Ứng dụng AI", "Deep Learning"]', 'draft', b'1', '2026-01-09 11:22:58', '2026-01-09 11:22:58'),
	(313, 'Kiểm tra nhanh Tiếng Anh', 'Kiến thức cơ bản tiếng Anh mức độ dễ cho mọi người.', 2, 'Beginner', 15, '#fb1313', 70, 5, '["Học viên có thể nhận biết và sử dụng các thì cơ bản (hiện tại đơn, quá khứ đơn).", "Học viên có thể sử dụng các đại từ nhân xưng và tính từ sở hữu.", "Học viên có thể đặt câu hỏi đơn giản và trả lời chúng.", "Học viên có thể hiểu và sử dụng các từ vựng thông dụng về gia đình, bạn bè, và công việc."]', '["Không yêu cầu kiến thức trước.", "Khả năng đọc và hiểu các hướng dẫn cơ bản."]', '["tiếng Anh", "cơ bản", "người mới bắt đầu", "grammar", "vocabulary"]', 'draft', b'1', '2026-01-09 20:35:18', '2026-01-09 20:35:18');
