INSERT INTO `flashcards` (`id`, `flashcard_set_id`, `front_text`, `back_text`, `explanation`, `created_at`, `updated_at`) VALUES
	(1, 2, 'API là gì?', 'API là giao diện cho phép các hệ thống giao tiếp với nhau.', 'Frontend gửi request đến API của backend để lấy dữ liệu hoặc thực hiện các thao tác như đăng nhập, lưu dữ liệu.', '2026-05-15 08:35:00', '2026-05-15 08:35:00'),
	(2, 2, 'React là gì?', 'là thư viện JavaScript dùng để xây dựng giao diện người dùng', NULL, '2026-05-15 08:35:01', '2026-05-15 08:35:01'),
	(3, 2, 'JavaScript là gì?', 'JavaScript là ngôn ngữ lập trình giúp trang web có tính tương tác.', NULL, '2026-05-15 08:35:01', '2026-05-15 08:35:01');
