INSERT INTO `groups` (`id`, `name`, `slug`, `description`, `cover_image`, `members_count`, `owner_id`, `visibility`, `created_at`, `updated_at`) VALUES
	(5, 'Cộng đồng học tập online', 'cong-dong-hoc-tap-online-69364744bb1ce', 'Nếu bạn muốn tham gia chat, thì cộng đồng này là lựa chọn chính xác nhất.', '/storage/groups/zD3PnkXCRA1bFCPJ08GEhJG9IQbWDJgfWAGnntsb.png', 2, 1, 'public', '2025-12-07 20:34:28', '2026-01-09 11:27:45'),
	(6, 'Nhóm học Tiếng Anh B1', 'nhom-hoc-tieng-anh-b1-6961ab72c61e0', 'Cùng nhau ôn tập tiếng Anh cùng nhau, cộng đồng học tiếng Anh', '/storage/groups/9IyLFiuxUbtqPRkZEl2Xg49QTdUCMC2eEiKPLqoz.jpg', 1, 1, 'public', '2026-01-09 18:29:23', '2026-01-09 18:29:23'),
	(7, 'Nhóm Lập trình F4 CNTT', 'nhom-lap-trinh-f4-cntt-6961ac0530b03', 'Học lập trình cùng nhau, và các môn học khác', '/storage/groups/XRoqbp5W8a9zQSEb5OFI2EF9Va8qaVKgWHAu7NK9.jpg', 2, 1, 'public', '2026-01-09 18:31:49', '2026-01-09 18:38:29'),
	(9, 'Nhóm Mới cho tất cả', 'nhom-moi-cho-tat-ca-6961ad2086fca', 'Lập trình java, python, php cơ bản dành cho người mới bắt đầu, bài thực hành,....', '/storage/groups/2b4W4zGBASrZZmiigbrWXInHyUcG7C7Ehk9EXWDD.jpg', 1, 1, 'private', '2026-01-09 18:36:32', '2026-01-09 18:36:32');
