INSERT INTO `questions` (`id`, `content`, `options`, `answer`, `explanation`, `type`, `points`, `created_at`, `updated_at`) VALUES
	(1020, 'Đơn vị cơ bản nhất để đo lượng thông tin trong máy tính là gì?', '{"A": "Byte", "B": "Kilobyte (KB)", "C": "Bit", "D": "Hertz (Hz)"}', 'C', 'Bit (viết tắt của binary digit) là đơn vị thông tin nhỏ nhất trong máy tính, chỉ có hai giá trị là 0 hoặc 1.', 'multiple_choice', 2, '2025-09-07 07:13:01', '2025-12-04 05:56:34'),
	(2078, 'Bộ phận nào của máy tính được coi là \'bộ não\'?', '{"A": "CPU", "B": "RAM", "C": "Ổ cứng", "D": "Card đồ họa"}', 'A', NULL, 'multiple_choice', 1, '2025-12-10 07:25:37', '2025-12-10 07:25:37'),
	(2080, 'Đâu là một hệ điều hành phổ biến?', '{"A": "Microsoft Word", "B": "Google Chrome", "C": "Windows", "D": "Adobe Photoshop"}', 'C', NULL, 'multiple_choice', 1, '2025-12-10 07:25:37', '2025-12-10 07:25:37'),
	(2081, 'Chuột máy tính dùng để làm gì?', '{"A": "In tài liệu", "B": "Điều khiển con trỏ trên màn hình", "C": "Nghe nhạc", "D": "Chụp ảnh"}', 'B', NULL, 'multiple_choice', 1, '2025-12-10 07:25:37', '2025-12-10 07:25:37'),
	(2082, 'Đâu là một thiết bị lưu trữ dữ liệu?', '{"A": "Màn hình", "B": "Bàn phím", "C": "Ổ cứng", "D": "Loa"}', 'C', NULL, 'multiple_choice', 1, '2025-12-10 07:25:37', '2025-12-10 07:25:37'),
	(2088, 'Xu hướng phát triển CNTT&TT nào sau đây được dự đoán sẽ có sự gia tăng về số lượng và chủng loại thiết bị?', '{"A": "Điện toán đám mây", "B": "Dữ liệu lớn", "C": "Công nghệ di động", "D": "Internet kết nối vạn vật (IoT)"}', 'C', 'Công nghệ di động được dự đoán sẽ có sự gia tăng về số lượng và chủng loại thiết bị, với thế hệ mạng thông tin di động chiếm ưu thế.', 'multiple_choice', 1, '2026-01-09 09:43:47', '2026-01-09 09:43:47'),
	(2089, 'Nguy cơ nào sau đây liên quan đến hành vi vô tình hoặc cố ý của người dùng hợp pháp gây ra sự cố hoặc lỗi khai thác hệ thống?', '{"A": "Lỗi phần mềm", "B": "Nguy cơ phá hoại", "C": "Lỗi người dùng hoặc lỗi hệ thống", "D": "Vi phạm sở hữu trí tuệ"}', 'C', 'Lỗi người dùng hoặc lỗi hệ thống bao gồm các hành vi vô tình (do thiếu hiểu biết, thiếu cẩn thận) hoặc cố ý của người dùng hợp pháp.', 'multiple_choice', 1, '2026-01-09 09:43:47', '2026-01-09 09:43:47'),
	(2090, 'Làn sóng phát triển CNTT&TT thứ ba tập trung vào các yếu tố nào?', '{"A": "Mạng viễn thông, mạng cục bộ, Mainframe", "B": "Thế hệ mạng di động mới, Internet, công nghệ Web", "C": "Dữ liệu lớn, IoT, An toàn không gian mạng, kết nối thực ảo", "D": "Phần mềm ứng dụng văn phòng"}', 'C', 'Làn sóng thứ ba tập trung vào Dữ liệu lớn, IoT, An toàn không gian mạng và kết nối thực ảo.', 'multiple_choice', 1, '2026-01-09 09:43:47', '2026-01-09 09:43:47'),
	(2091, 'Vấn đề nào sau đây gắn liền với sự phát triển của CNTT&TT và tốc độ, phạm vi kết nối mạng ngày càng tăng?', '{"A": "Phát triển phần mềm ứng dụng", "B": "An toàn không gian mạng", "C": "Ứng dụng trí tuệ nhân tạo", "D": "Phát triển phần cứng máy tính"}', 'B', 'An toàn không gian mạng là một vấn đề gắn liền với CNTT&TT, đặc biệt khi tốc độ và phạm vi kết nối mạng ngày càng tăng.', 'multiple_choice', 1, '2026-01-09 09:43:47', '2026-01-09 09:43:47'),
	(2092, 'Loại nguy cơ nào liên quan đến việc sao chép hoặc sử dụng trái phép các bí mật thương mại, bản quyền thương hiệu, phát minh sáng chế?', '{"A": "Nguy cơ phần mềm", "B": "Vi phạm sở hữu trí tuệ", "C": "Nguy cơ phá hoại", "D": "Lỗi người dùng"}', 'B', 'Vi phạm sở hữu trí tuệ bao gồm các hành vi như gián điệp, bẻ khóa bản quyền số, xâm phạm bí mật thương mại, bản quyền thương hiệu, phát minh sáng chế.', 'multiple_choice', 1, '2026-01-09 09:43:47', '2026-01-09 09:43:47'),
	(2094, 'Đâu là một ví dụ về thuật toán Supervised Learning?', '{"A": "K-Means Clustering", "B": "Principal Component Analysis (PCA)", "C": "Linear Regression", "D": "Apriori Algorithm"}', 'C', 'Linear Regression là một thuật toán Supervised Learning, trong đó mô hình được huấn luyện trên dữ liệu đã được gán nhãn.', 'multiple_choice', 1, '2026-01-09 10:54:39', '2026-01-09 10:54:39'),
	(2095, 'Unsupervised Learning là gì?', '{"A": "Một loại Machine Learning sử dụng dữ liệu đã được gán nhãn để huấn luyện mô hình.", "B": "Một loại Machine Learning sử dụng dữ liệu chưa được gán nhãn để tìm ra cấu trúc ẩn.", "C": "Một kỹ thuật để giám sát hiệu suất của mô hình Machine Learning.", "D": "Một phương pháp để cải thiện độ chính xác của mô hình."}', 'B', 'Unsupervised Learning làm việc với dữ liệu không có nhãn và cố gắng khám phá các mẫu hoặc cấu trúc ẩn.', 'multiple_choice', 1, '2026-01-09 10:54:39', '2026-01-09 10:54:39'),
	(2096, 'Trong Machine Learning, \'feature\' là gì?', '{"A": "Một thuật toán cụ thể được sử dụng để huấn luyện mô hình.", "B": "Một thuộc tính hoặc đặc điểm của dữ liệu được sử dụng làm đầu vào cho mô hình.", "C": "Một phương pháp để đánh giá hiệu suất của mô hình.", "D": "Một tham số được sử dụng để điều chỉnh mô hình."}', 'B', 'Feature là một thuộc tính hoặc đặc điểm của dữ liệu, ví dụ như chiều cao, cân nặng, màu sắc, v.v.', 'multiple_choice', 1, '2026-01-09 10:54:39', '2026-01-09 10:54:39'),
	(2097, 'True or False: Overfitting xảy ra khi mô hình Machine Learning hoạt động rất tốt trên dữ liệu huấn luyện nhưng kém trên dữ liệu mới.', '{"A": "True", "B": "False"}', 'A', 'Đúng. Overfitting xảy ra khi mô hình học quá kỹ dữ liệu huấn luyện, bao gồm cả nhiễu, dẫn đến khả năng khái quát hóa kém trên dữ liệu mới.', 'true_false', 1, '2026-01-09 10:54:39', '2026-01-09 10:54:39'),
	(2098, 'Machine Learning là gì?', '{"A": "Một loại robot có khả năng tự suy nghĩ.", "B": "Một lĩnh vực của khoa học máy tính cho phép máy tính học từ dữ liệu mà không cần được lập trình rõ ràng.", "C": "Một phương pháp để tạo ra các chương trình máy tính nhanh hơn.", "D": "Một công cụ để tự động hóa các tác vụ văn phòng."}', 'B', 'Machine Learning tập trung vào việc cho phép máy tính học hỏi từ dữ liệu để đưa ra dự đoán hoặc quyết định mà không cần lập trình cụ thể cho từng trường hợp.', 'multiple_choice', 1, '2026-01-09 10:55:01', '2026-01-09 10:55:01'),
	(2099, 'Loại Machine Learning nào mà mô hình học từ dữ liệu đã được gán nhãn?', '{"A": "Supervised Learning", "B": "Unsupervised Learning", "C": "Reinforcement Learning", "D": "Deep Learning"}', 'A', 'Supervised Learning sử dụng dữ liệu đã được gán nhãn (ví dụ: ảnh mèo và chó đã được gán nhãn \'mèo\' hoặc \'chó\') để huấn luyện mô hình.', 'multiple_choice', 1, '2026-01-09 10:55:01', '2026-01-09 10:55:01'),
	(2100, 'Thuật toán nào sau đây thuộc loại Supervised Learning?', '{"A": "K-means Clustering", "B": "Principal Component Analysis (PCA)", "C": "Linear Regression", "D": "Association Rule Mining"}', 'C', 'Linear Regression là một thuật toán Supervised Learning được sử dụng để dự đoán giá trị liên tục dựa trên các biến đầu vào.', 'multiple_choice', 1, '2026-01-09 10:55:01', '2026-01-09 10:55:01'),
	(2101, 'Unsupervised Learning được sử dụng để làm gì?', '{"A": "Dự đoán nhãn cho dữ liệu mới.", "B": "Tìm kiếm cấu trúc ẩn trong dữ liệu không được gán nhãn.", "C": "Huấn luyện một tác nhân để đưa ra quyết định trong một môi trường.", "D": "Phân loại dữ liệu thành các nhóm đã biết."}', 'B', 'Unsupervised Learning khám phá các mẫu, cấu trúc hoặc mối quan hệ ẩn trong dữ liệu mà không cần nhãn.', 'multiple_choice', 1, '2026-01-09 10:55:01', '2026-01-09 10:55:01'),
	(2102, 'True or False: Overfitting xảy ra khi mô hình học quá tốt trên dữ liệu huấn luyện và không thể khái quát hóa tốt cho dữ liệu mới.', '{"A": "True", "B": "False"}', 'A', 'Overfitting là tình trạng mô hình học quá sát dữ liệu huấn luyện, bao gồm cả nhiễu, dẫn đến hiệu suất kém trên dữ liệu mới.', 'true_false', 1, '2026-01-09 10:55:01', '2026-01-09 10:55:01'),
	(2103, 'What is the primary goal of image segmentation?', '{"A": "To enhance the image quality", "B": "To compress the image size", "C": "To divide an image into meaningful regions", "D": "To convert an image to grayscale"}', 'C', 'Image segmentation aims to partition an image into multiple regions that correspond to different objects or parts of objects.', 'multiple_choice', 1, '2026-01-09 11:08:09', '2026-01-09 11:08:09'),
	(2104, 'Which of the following is NOT a basic approach to image segmentation?', '{"A": "Thresholding based on grayscale values", "B": "Region-based segmentation", "C": "Edge-based segmentation", "D": "Image encryption"}', 'D', 'Image encryption is not a segmentation technique; it\'s a security measure to protect image data.', 'multiple_choice', 1, '2026-01-09 11:08:09', '2026-01-09 11:08:09'),
	(2105, 'In Simple Thresholding, what happens to a pixel if its value is greater than or equal to the threshold (T) when using THRESH_BINARY?', '{"A": "The pixel value is set to 0", "B": "The pixel value remains unchanged", "C": "The pixel value is set to MAXVAL", "D": "The pixel value is inverted"}', 'C', 'With THRESH_BINARY, if a pixel\'s value is greater than or equal to the threshold, it is assigned the maximum value (MAXVAL).', 'multiple_choice', 1, '2026-01-09 11:08:09', '2026-01-09 11:08:09'),
	(2106, 'What is the purpose of Adaptive Thresholding?', '{"A": "To apply a single threshold value to the entire image", "B": "To adjust the threshold value based on local image characteristics", "C": "To convert a color image to grayscale", "D": "To remove noise from the image"}', 'B', 'Adaptive thresholding adjusts the threshold value for each pixel based on the surrounding region, making it suitable for images with varying lighting conditions.', 'multiple_choice', 1, '2026-01-09 11:08:09', '2026-01-09 11:08:09'),
	(2107, 'Which of the following is a morphological operation used in image processing?', '{"A": "Convolution", "B": "Fourier Transform", "C": "Dilation", "D": "Histogram Equalization"}', 'C', 'Dilation is a morphological operation that expands the boundaries of objects in an image.', 'multiple_choice', 1, '2026-01-09 11:08:09', '2026-01-09 11:08:09'),
	(2108, 'Đâu là thành phần cơ bản nhất của một mạng nơ-ron nhân tạo?', '{"A": "Hàm mất mát (Loss function)", "B": "Nơ-ron (Neuron)", "C": "Thuật toán tối ưu hóa (Optimization algorithm)", "D": "Bộ dữ liệu huấn luyện (Training dataset)"}', 'B', 'Nơ-ron là đơn vị tính toán cơ bản, kết nối với nhau để tạo thành mạng nơ-ron.', 'multiple_choice', 1, '2026-01-09 11:12:09', '2026-01-09 11:12:09'),
	(2109, 'Hàm kích hoạt (Activation function) có vai trò gì trong mạng nơ-ron?', '{"A": "Tính toán giá trị mất mát (loss) của mô hình.", "B": "Quyết định xem nơ-ron có được kích hoạt hay không dựa trên đầu vào.", "C": "Cập nhật trọng số (weight) của các kết nối.", "D": "Chuẩn hóa dữ liệu đầu vào."}', 'B', 'Hàm kích hoạt quyết định đầu ra của một nơ-ron dựa trên tổng đầu vào có trọng số của nó.', 'multiple_choice', 1, '2026-01-09 11:12:09', '2026-01-09 11:12:09'),
	(2110, 'Quá trình lan truyền ngược (Backpropagation) được sử dụng để làm gì trong quá trình huấn luyện mạng nơ-ron?', '{"A": "Tính toán độ chính xác (accuracy) của mô hình.", "B": "Lan truyền dữ liệu đầu vào qua mạng.", "C": "Tính toán gradient của hàm mất mát (loss function) để cập nhật trọng số.", "D": "Chọn kiến trúc mạng nơ-ron phù hợp."}', 'C', 'Backpropagation là thuật toán chính để tính toán gradient, từ đó cập nhật trọng số để giảm thiểu sai số.', 'multiple_choice', 1, '2026-01-09 11:12:09', '2026-01-09 11:12:09'),
	(2111, 'Đâu là một ví dụ về thuật toán tối ưu hóa (optimization algorithm) thường được sử dụng trong Deep Learning?', '{"A": "K-Means Clustering", "B": "Support Vector Machine (SVM)", "C": "Gradient Descent", "D": "Principal Component Analysis (PCA)"}', 'C', 'Gradient Descent và các biến thể của nó (Adam, SGD, RMSprop) là những thuật toán tối ưu hóa phổ biến.', 'multiple_choice', 1, '2026-01-09 11:12:09', '2026-01-09 11:12:09'),
	(2112, 'True or False: Mạng nơ-ron tích chập (Convolutional Neural Network - CNN) thường được sử dụng cho các bài toán liên quan đến xử lý ảnh.', '{"A": "True", "B": "False"}', 'A', 'CNNs are specifically designed to process data that has a grid-like topology, such as images.', 'true_false', 1, '2026-01-09 11:12:09', '2026-01-09 11:12:09'),
	(2113, 'Công nghệ Thông tin (CNTT) là gì?', '{"A": "Ngành khoa học nghiên cứu về vũ trụ.", "B": "Ngành khoa học nghiên cứu về việc thu thập, xử lý, lưu trữ, truyền tải và sử dụng thông tin.", "C": "Ngành khoa học nghiên cứu về động vật.", "D": "Ngành khoa học nghiên cứu về thực vật."}', 'B', 'Công nghệ Thông tin là ngành khoa học nghiên cứu về việc thu thập, xử lý, lưu trữ, truyền tải và sử dụng thông tin.', 'multiple_choice', 1, '2026-01-09 11:17:34', '2026-01-09 11:17:34'),
	(2114, 'Lĩnh vực nào sau đây KHÔNG phải là ứng dụng của CNTT?', '{"A": "Y tế", "B": "Giáo dục", "C": "Nông nghiệp", "D": "Khảo cổ học"}', 'D', 'CNTT được ứng dụng rộng rãi trong y tế, giáo dục, nông nghiệp, nhưng không trực tiếp liên quan đến khảo cổ học.', 'multiple_choice', 1, '2026-01-09 11:17:34', '2026-01-09 11:17:34'),
	(2115, 'Ngôn ngữ lập trình nào thường được sử dụng để phát triển ứng dụng di động Android?', '{"A": "Python", "B": "Java/Kotlin", "C": "C++", "D": "HTML/CSS"}', 'B', 'Java và Kotlin là hai ngôn ngữ lập trình chính được sử dụng để phát triển ứng dụng di động Android.', 'multiple_choice', 1, '2026-01-09 11:17:34', '2026-01-09 11:17:34'),
	(2116, 'Điện toán đám mây (Cloud Computing) là gì?', '{"A": "Một loại máy tính cá nhân.", "B": "Mô hình cung cấp tài nguyên điện toán theo yêu cầu qua internet.", "C": "Một loại phần mềm diệt virus.", "D": "Một loại mạng xã hội."}', 'B', 'Điện toán đám mây là mô hình cung cấp tài nguyên điện toán theo yêu cầu qua internet.', 'multiple_choice', 1, '2026-01-09 11:17:34', '2026-01-09 11:17:34'),
	(2117, 'True or False: Trí tuệ nhân tạo (AI) chỉ có thể được sử dụng trong lĩnh vực khoa học viễn tưởng.', '{"A": "True", "B": "False"}', 'B', 'Trí tuệ nhân tạo (AI) được ứng dụng rộng rãi trong nhiều lĩnh vực thực tế như y tế, giao thông, tài chính, và nhiều lĩnh vực khác.', 'true_false', 1, '2026-01-09 11:17:34', '2026-01-09 11:17:34'),
	(2118, 'AI (Trí tuệ Nhân tạo) là gì?', '{"A": "Một loại robot có khả năng suy nghĩ và hành động như con người.", "B": "Một lĩnh vực của khoa học máy tính tập trung vào việc tạo ra các hệ thống thông minh.", "C": "Một ứng dụng cụ thể được sử dụng để tự động hóa các tác vụ.", "D": "Một loại ngôn ngữ lập trình mới."}', 'B', 'AI là một lĩnh vực rộng lớn của khoa học máy tính, nhằm mục đích tạo ra các hệ thống có khả năng mô phỏng trí thông minh của con người.', 'multiple_choice', 1, '2026-01-09 11:22:58', '2026-01-09 11:22:58'),
	(2119, 'Ứng dụng nào sau đây KHÔNG phải là một ứng dụng phổ biến của AI?', '{"A": "Xe tự lái.", "B": "Phần mềm nhận dạng khuôn mặt.", "C": "Hệ thống đề xuất sản phẩm trực tuyến.", "D": "Máy pha cà phê tự động."}', 'D', 'Máy pha cà phê tự động có thể sử dụng một số công nghệ tự động hóa, nhưng không nhất thiết phải dựa trên các thuật toán AI phức tạp.', 'multiple_choice', 1, '2026-01-09 11:22:58', '2026-01-09 11:22:58'),
	(2120, 'Machine Learning (Học máy) là gì?', '{"A": "Một phương pháp lập trình truyền thống.", "B": "Một loại phần cứng máy tính đặc biệt.", "C": "Một nhánh của AI cho phép máy tính học hỏi từ dữ liệu mà không cần được lập trình rõ ràng.", "D": "Một ngôn ngữ lập trình mới."}', 'C', 'Machine Learning là một nhánh quan trọng của AI, cho phép máy tính cải thiện hiệu suất của chúng thông qua kinh nghiệm (dữ liệu).', 'multiple_choice', 1, '2026-01-09 11:22:58', '2026-01-09 11:22:58'),
	(2121, 'AI có thể được sử dụng trong lĩnh vực y tế để làm gì?', '{"A": "Chẩn đoán bệnh.", "B": "Phát triển thuốc mới.", "C": "Cá nhân hóa phương pháp điều trị.", "D": "Tất cả các đáp án trên."}', 'D', 'AI có tiềm năng to lớn trong việc cải thiện hiệu quả và độ chính xác trong nhiều khía cạnh của lĩnh vực y tế.', 'multiple_choice', 1, '2026-01-09 11:22:58', '2026-01-09 11:22:58'),
	(2122, 'Câu nào sau đây là ĐÚNG về tác động của AI đối với thị trường lao động?', '{"A": "AI sẽ thay thế hoàn toàn tất cả các công việc.", "B": "AI chỉ ảnh hưởng đến các công việc chân tay.", "C": "AI có thể tự động hóa một số công việc, nhưng cũng tạo ra những công việc mới.", "D": "AI không có tác động gì đến thị trường lao động."}', 'C', 'Mặc dù AI có thể tự động hóa một số công việc hiện tại, nhưng nó cũng tạo ra nhu cầu về các kỹ năng mới và các công việc liên quan đến phát triển, triển khai và bảo trì các hệ thống AI.', 'multiple_choice', 1, '2026-01-09 11:22:58', '2026-01-09 11:22:58'),
	(2123, 'Chọn đáp án đúng: I ______ a student.', '{"A": "am", "B": "is", "C": "are", "D": "be"}', 'A', '"I" đi với động từ "am".', 'multiple_choice', 1, '2026-01-09 20:35:18', '2026-01-09 20:35:18'),
	(2124, 'Chọn đáp án đúng: They ______ from Vietnam.', '{"A": "is", "B": "am", "C": "are", "D": "be"}', 'C', '"They" đi với động từ "are".', 'multiple_choice', 1, '2026-01-09 20:35:18', '2026-01-09 20:35:18'),
	(2125, 'Chọn đáp án đúng: What is ______ name?', '{"A": "he", "B": "his", "C": "him", "D": "she"}', 'B', 'Cần sử dụng tính từ sở hữu "his".', 'multiple_choice', 1, '2026-01-09 20:35:18', '2026-01-09 20:35:18'),
	(2126, 'Chọn đáp án đúng: I ______ to the cinema yesterday.', '{"A": "go", "B": "went", "C": "going", "D": "gone"}', 'B', 'Cần sử dụng thì quá khứ đơn của "go" là "went".', 'multiple_choice', 1, '2026-01-09 20:35:18', '2026-01-09 20:35:18'),
	(2127, 'True or False: \'She\' is a pronoun.', '{"A": "True", "B": "False"}', 'A', '\'She\' là một đại từ nhân xưng.', 'true_false', 1, '2026-01-09 20:35:18', '2026-01-09 20:35:18');
